#!/usr/bin/env bash
set -eu
cd "$(dirname "$0")"
mkdir -p build
trace_flag=""
if [ "${S2_TRACE:-0}" = 1 ]; then trace_flag=-DS2_TRACE; fi
g++ $trace_flag -std=c++17 -O2 -Wall -Wextra -Werror -Wno-misleading-indentation scene_renderer.cpp sprite_renderer.cpp actor_logic.cpp collision.cpp horizontal_input.cpp player_prototype.cpp player_states.cpp actor_frame.cpp dynamic_collision.cpp event_dispatch.cpp scene_objects.cpp script_vm.cpp generic_actor.cpp generic_runtime.cpp generic_reactions.cpp audio_requests.cpp actor_interactions.cpp world_queries.cpp shrek_interactions.cpp shrek_reactions.cpp shrek_carry.cpp shrek_grab.cpp shrek_locomotion.cpp shrek_player_frame.cpp native_session.cpp world_effect_requests.cpp spawner_actor.cpp minigame_controller.cpp bonus_rewards.cpp dialogue_runtime.cpp dialogue_presentation.cpp frontend.cpp frontend_motion.cpp campaign_view.cpp campaign_player.cpp donkey_player.cpp puss_player.cpp puss_bonus.cpp projectile_actor.cpp campaign_special.cpp fairy_boss.cpp puss_boss.cpp -o build/scene_renderer
g++ $trace_flag -std=c++17 -O2 -Wall -Wextra -Werror -Wno-misleading-indentation -DS2_LIBRARY_ONLY -fPIC -shared scene_renderer.cpp sprite_renderer.cpp actor_logic.cpp collision.cpp horizontal_input.cpp player_prototype.cpp player_states.cpp actor_frame.cpp dynamic_collision.cpp event_dispatch.cpp scene_objects.cpp script_vm.cpp generic_actor.cpp generic_runtime.cpp generic_reactions.cpp audio_requests.cpp actor_interactions.cpp world_queries.cpp shrek_interactions.cpp shrek_reactions.cpp shrek_carry.cpp shrek_grab.cpp shrek_locomotion.cpp shrek_player_frame.cpp native_session.cpp world_effect_requests.cpp spawner_actor.cpp minigame_controller.cpp bonus_rewards.cpp dialogue_runtime.cpp dialogue_presentation.cpp frontend.cpp frontend_motion.cpp campaign_view.cpp campaign_player.cpp donkey_player.cpp puss_player.cpp puss_bonus.cpp projectile_actor.cpp campaign_special.cpp fairy_boss.cpp puss_boss.cpp -o build/libshrek_scene.so.pending
mv build/libshrek_scene.so.pending build/libshrek_scene.so
